import json
from itertools import permutations

names = ["fuel", "grain", "livestock", "machinery", "produce", "textiles"]
sols = []
for p in permutations(range(1, 7)):
    pos = dict(zip(names, p))
    if not pos["grain"] > pos["livestock"]:
        continue
    if not pos["livestock"] > pos["textiles"]:
        continue
    if not pos["produce"] > pos["fuel"]:
        continue
    if abs(pos["textiles"] - pos["produce"]) != 1:
        continue
    if abs(pos["machinery"] - pos["grain"]) != 2:
        continue
    sols.append(pos)

determined = 0
detail = {}
for b in range(1, 7):
    cargos = {n for s in sols for n in names if s[n] == b}
    detail[b] = sorted(cargos)
    if len(cargos) == 1:
        determined += 1

mapping = {1: "one", 2: "two", 3: "three", 4: "four", 5: "five", 6: "six"}
opts = {"two": "A", "three": "B", "four": "C", "five": "D", "six": "E"}
if not sols:
    print("UNSUPPORTED")
else:
    word = mapping[determined]
    print(json.dumps({
        "final_answer": opts.get(word, "UNSUPPORTED"),
        "evidence": {"num_solutions": len(sols), "determined_count": determined, "bays": detail}
    }))
